const allItems = $input.all().map(i => i.json);

// Payload is the one that has "meta" field
const payload = allItems.find(i => i.meta !== undefined);

// Runs rows — have row_number AND triggered_at but NOT timestamp
const rows = allItems.filter(i => i.row_number !== undefined && i.triggered_at !== undefined && i.timestamp === undefined);

// Image rows — have timestamp AND summary (picture analysis rows)
const imageRows = allItems.filter(i => i.timestamp !== undefined && i.summary !== undefined);

// ----------------------------------------------------------------
// RUNS HISTORY
// ----------------------------------------------------------------
let runsHistory = null;

if (rows.length > 0) {
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  const last7days = rows.filter(r => new Date(r.triggered_at) >= sevenDaysAgo);

  const avg = (field) => {
    const values = last7days.map(r => {
      const sensors = typeof r.sensors === 'string' ? JSON.parse(r.sensors) : r.sensors;
      return parseFloat(sensors?.[field]);
    }).filter(v => !isNaN(v));
    if (values.length === 0) return null;
    return parseFloat((values.reduce((a, b) => a + b, 0) / values.length).toFixed(2));
  };

  const waterByDay = {};
  last7days.forEach(r => {
    const day = r.triggered_at?.slice(0, 10);
    if (!day) return;
    const actuators = typeof r.actuators === 'string' ? JSON.parse(r.actuators) : r.actuators;
    const pump = Array.isArray(actuators) ? actuators.find(a => a.type === 'pump') : null;
    const duration = parseFloat(pump?.duration_minutes) || 0;
    waterByDay[day] = (waterByDay[day] || 0) + duration;
  });

  const water7d = Object.entries(waterByDay).map(([day, minutes]) => ({
    day,
    total_pump_minutes: parseFloat(minutes.toFixed(2))
  }));

  runsHistory = {
    averages_7d: {
      soil_moisture: avg('soil_moisture'),
      temperature:   avg('temperature'),
      air_humidity:  avg('air_humidity'),
      luminosity:    avg('luminosity')
    },
    water_consumption_7d: water7d,
    last_3_runs: last7days.slice(-3).map(r => {
      const sensors   = typeof r.sensors   === 'string' ? JSON.parse(r.sensors)   : r.sensors;
      const actuators = typeof r.actuators === 'string' ? JSON.parse(r.actuators) : r.actuators;
      const pump = Array.isArray(actuators) ? actuators.find(a => a.type === 'pump') : null;
      const fan  = Array.isArray(actuators) ? actuators.find(a => a.type === 'fan')  : null;
      return {
        triggered_at:          r.triggered_at,
        soil_moisture:         sensors?.soil_moisture         ?? null,
        temperature:           sensors?.temperature           ?? null,
        air_humidity:          sensors?.air_humidity          ?? null,
        luminosity:            sensors?.luminosity            ?? null,
        pump_decision:         pump?.classification           ?? null,
        pump_duration_minutes: pump?.duration_minutes         ?? null,
        fan_decision:          fan?.classification            ?? null,
        fan_duration_minutes:  fan?.duration_minutes          ?? null
      };
    })
  };
}

// ----------------------------------------------------------------
// IMAGE HISTORY
// ----------------------------------------------------------------
let imagesHistory = null;

if (imageRows.length > 0) {
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  const last7daysImages = imageRows.filter(r => new Date(r.timestamp) >= sevenDaysAgo);

  const parseFeatures = (raw) => {
    if (!raw) return {};
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(raw); } catch { return {}; }
  };

  const parseDecision = (raw) => {
    if (!raw) return { pump: null, fan: null };
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(raw); } catch { return { pump: null, fan: null }; }
  };

  const avgNum = (field) => {
    const values = last7daysImages.map(r => parseFloat(r[field])).filter(v => !isNaN(v));
    if (values.length === 0) return null;
    return parseFloat((values.reduce((a, b) => a + b, 0) / values.length).toFixed(2));
  };

  const avgBool = (field) => {
    const values = last7daysImages.map(r => {
      const features = parseFeatures(r.features);
      return features[field];
    }).filter(v => v !== null && v !== undefined);
    if (values.length === 0) return null;
    const trueCount = values.filter(v => v === true || v === 'true').length;
    return trueCount / values.length >= 0.5;
  };

  const avgMode = (field) => {
    const values = last7daysImages.map(r => {
      const features = parseFeatures(r.features);
      return features[field];
    }).filter(v => v !== null && v !== undefined);
    if (values.length === 0) return null;
    const freq = {};
    values.forEach(v => { freq[v] = (freq[v] || 0) + 1; });
    return Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0];
  };

  const decisionStats = (actuator) => {
    const decisions = last7daysImages.map(r => {
      const d = parseDecision(r.actuator_decisions);
      return d?.[actuator] ?? null;
    }).filter(v => v !== null);
    if (decisions.length === 0) return null;
    const freq = {};
    decisions.forEach(v => { freq[v] = (freq[v] || 0) + 1; });
    return Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0];
  };

  const last3 = last7daysImages.slice(-3).map(r => {
    const features = parseFeatures(r.features);
    const decision = parseDecision(r.actuator_decisions);
    return {
      timestamp:             r.timestamp,
      image_summary:         r.summary ?? null,
      confidence:            parseFloat(r.confidence) || null,
      rain_detected:         features.rain_detected         ?? null,
      water_on_leaves:       features.water_on_leaves       ?? null,
      cloud_cover:           features.cloud_cover           ?? null,
      lighting_level:        features.lighting_level        ?? null,
      shadows_present:       features.shadows_present       ?? null,
      plant_motion_detected: features.plant_motion_detected ?? null,
      motion_intensity:      features.motion_intensity      ?? null,
      decision: {
        pump: decision?.pump ?? null,
        fan:  decision?.fan  ?? null
      }
    };
  });

  imagesHistory = {
    averages_7d: {
      confidence:            avgNum('confidence'),
      rain_detected:         avgBool('rain_detected'),
      water_on_leaves:       avgBool('water_on_leaves'),
      cloud_cover:           avgMode('cloud_cover'),
      lighting_level:        avgMode('lighting_level'),
      shadows_present:       avgBool('shadows_present'),
      plant_motion_detected: avgBool('plant_motion_detected'),
      motion_intensity:      avgMode('motion_intensity')
    },
    decision_stats_7d: {
      pump: decisionStats('pump'),
      fan:  decisionStats('fan')
    },
    last_3_runs: last3
  };
}

// ----------------------------------------------------------------
// BUILD FINAL HISTORY
// ----------------------------------------------------------------
payload.history = {
  runs:   runsHistory,
  images: imagesHistory
};

return [{ json: payload }];
